mapper.sql:
assess_projects AS (
    SELECT p.id, p.title, p.start_time, p.end_time
    FROM sys_project p
    WHERE p.status <> 3
    AND p.id = #{param.projectId}
    AND p.start_time <= #{param.startTime}
    AND p.end_time >= #{param.endTime}
),
assess_flows AS (
    SELECT p.id AS projectId, ft.id, ft.u_id, ft.role_id
    FROM assess_projects p
    JOIN sys_flow f ON f.p_id = p.id AND f.status = 1
    JOIN sys_flow_task ft ON ft.parent_id = f.id AND ft.status = 1 AND ft.type = 'CC'
)

WITH , assess_candidates AS (
SELECT DISTINCT p.id AS projectId, r.u_id AS userId FROM assess_projects p JOIN sys_result r ON r.p_id = p.id AND r.u_id = #{scope.operatorId}
SELECT f.projectId, u.user_id AS userId FROM assess_flows f JOIN JSON_TABLE(CAST(f.u_id AS JSON), '$[*]' COLUMNS ( userId INT PATH '$' ERROR ON EMPTY ERROR ON ERROR )) recipients ON TRUE JOIN sys_user u ON u.user_id = recipients.userId UNION SELECT f.projectId, u.user_id AS userId FROM assess_flows f JOIN JSON_TABLE(CAST(f.role_id AS JSON), '$[*]' COLUMNS ( roleId INT PATH '$' ERROR ON EMPTY ERROR ON ERROR )) recipients ON TRUE JOIN sys_user_role ur ON ur.role_id = recipients.roleId JOIN sys_user u ON u.user_id = ur.user_id
SELECT 0 AS projectId, 0 AS userId WHERE 1 = 0
), assess_visible AS ( SELECT c.projectId, c.userId FROM assess_candidates c JOIN sys_user u ON u.user_id = c.userId WHERE
1 = 1
EXISTS ( SELECT 1 FROM sys_user_role operator_role JOIN sys_role role ON role.role_id = operator_role.role_id JOIN sys_user_role target_role ON target_role.role_id = operator_role.role_id WHERE operator_role.user_id = #{scope.operatorId} AND target_role.user_id = c.userId AND role.weight <> 1
AND role.weight = 2
)
1 = 0
AND EXISTS (SELECT 1 FROM sys_user_role filter_role WHERE filter_role.user_id = c.userId AND filter_role.role_id = #{param.roleId})
AND LOCATE(CAST(#{param.nickName} AS BINARY), CAST(u.nick_name AS BINARY)) > 0
), assess_totals AS ( SELECT c.projectId, c.userId, COALESCE(SUM(r.score), 0) AS score, MIN(r.id) AS firstResultId FROM assess_visible c LEFT JOIN sys_result r ON r.p_id = c.projectId AND r.u_id = c.userId GROUP BY c.projectId, c.userId ), assess_rows AS ( SELECT a.projectId, a.userId, a.score, CASE WHEN first_result.is_finish = 1 THEN 1 ELSE 0 END AS status FROM assess_totals a LEFT JOIN sys_result first_result ON first_result.id = a.firstResultId ), assess_filtered AS ( SELECT projectId, userId, score, status FROM assess_rows
status = #{param.status}
)

mapper.select:
SELECT counted.total FROM (

SELECT COUNT(*) AS total FROM assess_filtered
) counted

select ta.u_id as uId,ta.role_id as roleId,po.id as projectId from sys_project as po,sys_flow as
fo,sys_flow_task as ta
where po.status != 3 and fo.status = 1 and ta.status = 1
and po.id = #{pId}
and po.start_time <= #{startTime}
and po.end_time >= #{endTime}
and po.id = fo.p_id and fo.id = ta.parent_id and ta.type = 'CC'

select start_time as startTime,end_time as endTime from sys_project where id = #{pId}
and start_time <= #{startTime}
and end_time >= #{endTime}

select ta.u_id as uId,ta.role_id as roleId,po.id as projectId,po.title as projectName from sys_project as
po,sys_flow as fo,sys_flow_task as ta
where po.status != 3 and fo.status = 1 and ta.status = 1
and po.id = #{pId}
and po.id = fo.p_id and fo.id = ta.parent_id and ta.type = 'CC'
and date_format(po.start_time,'%Y') = #{year}

select id,title from sys_project where date_format(start_time,'%Y') = #{year} and status = 1

    and id in

        #{pId}



    and college = #{college}

select id,title from sys_project where date_format(start_time,'%Y') = #{year} and status = 1

    and id in

        #{pId}

mapper.update:
update sys_project
set status = 1,create_time = now()
where id = #{id}

mapper.select:
select year(start_time) as startTime from sys_project where status != 3
and create_name = #{createName}
order by startTime desc

mapper.update:
update sys_project
set status = 0,create_time = null
where id = #{id}

mapper.select:
select start_time as startTime,end_time as endTime
from sys_project
where id = #{pId}

select count(*)
from sys_project
where title = #{title}

select distinct category
from sys_task
where p_id=#{projectId}
